script:
raw = repo.read("services.json")
data = json.decode(raw)
services = data.get("services", [])
enabled = [s for s in services if s.get("enabled") == True]
names = sorted([s["name"] for s in enabled])
total = 0
for s in enabled:
    total += int(s.get("port"))
ports = {}
for s in enabled:
    ports[s["name"]] = s.get("port")
all_info = []
for s in services:
    all_info.append({"name": s.get("name"), "enabled": s.get("enabled"), "port": s.get("port")})
result = {
    "enabled_services": names,
    "ports": ports,
    "sum_of_ports": total,
    "all_services": all_info,
}
return {"result": result, "root_files": repo.list(".")}
